using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Web.Script.Serialization;
namespace BF4Bots {public static class LocalRotation {
 public static bool Matches(string root,string host,int port){if(host!="127.0.0.1")return false;int pid=OneClick.PortOwner(port);return pid>0&&OneClick.SamePath(OneClick.ProcessPath(pid),Path.Combine(root,"Server\\bf4_Server_Final.exe"));}
 public static string Serialize(List<RotationEntry> entries){if(entries.Count<1||entries.Count>1000)throw new InvalidDataException("A rotação precisa de 1 a 1000 mapas.");foreach(var e in entries)if(!Regex.IsMatch(e.Map,@"^[A-Za-z0-9_]+$")||!Regex.IsMatch(e.Mode,@"^[A-Za-z0-9_]+$")||e.Rounds<1||e.Rounds>99)throw new InvalidDataException("Mapa, modo ou rodadas inválidos.");return String.Join("\r\n",entries.Select(e=>e.Map+" "+e.Mode+" "+e.Rounds))+"\r\n";}
 static void Atomic(string file,byte[] content){string temp=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllBytes(temp,content);File.Replace(temp,file,null);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static void Save(string root,Rcon r,List<RotationEntry> baseline,List<RotationEntry> target,string backup){string serialized=Serialize(target);var live=r.Maps();if(!Rcon.Same(baseline,live))throw new IOException("A rotação mudou em outro painel. Atualize antes de salvar.");string file=Path.Combine(root,"Server\\Instance\\Admin\\MapList.txt");byte[] previous=File.ReadAllBytes(file);Directory.CreateDirectory(Path.GetDirectoryName(backup));File.WriteAllText(backup,new JavaScriptSerializer().Serialize(live),Encoding.UTF8);File.WriteAllBytes(backup+".MapList.txt",previous);if(Config.Hash(File.ReadAllBytes(file))!=Config.Hash(previous))throw new IOException("O arquivo de rotação mudou durante a preparação.");Atomic(file,new UTF8Encoding(false).GetBytes(serialized));try{r.Command("mapList.load");if(!Rcon.Same(target,r.Maps()))throw new IOException("O servidor não confirmou a rotação carregada do arquivo.");}catch(Exception ex){try{Atomic(file,new UTF8Encoding(false).GetBytes(Serialize(live)));r.Command("mapList.load");if(!Rcon.Same(live,r.Maps()))throw new IOException("A lista ativa não foi restaurada.");Atomic(file,previous);}catch(Exception rollback){throw new IOException("Falha ao carregar/restaurar. Backup: "+backup+". "+rollback.Message);}throw new IOException("A rotação anterior foi restaurada. "+ex.Message);}}
 public static void SaveName(string root,string name){string file=Path.Combine(root,"Server\\Instance\\Admin\\Startup.txt");byte[] before=File.ReadAllBytes(file);string text=Performance.Set(Config.Decode(before),"vars.serverName","\""+name.Replace("\"","'")+"\""," ");string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BF4BotLauncher","server-name-backups");Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,DateTime.Now.ToString("yyyyMMdd-HHmmssfff")+".txt"),before);Atomic(file,new UTF8Encoding(false).GetBytes(text));}
}}
